import {WebSocket} from 'ws';
import type {SessionEntry} from '../../types/session.js';
import type {OutgoingMessage} from '../../types/messages.js';
import type {SessionSummaryFrame} from '../../types/messages.js';
import type {ConversationSummary} from '../../types/messages.js';

export function sendJson(ws: WebSocket, message: OutgoingMessage): void {
  ws.send(JSON.stringify(message));
}

export function sendUpsert(ws: WebSocket, index: number, entry: SessionEntry): void {
  sendJson(ws, {type: 'entry_upsert', index, entry});
}

export function sendDelta(ws: WebSocket, index: number, delta: string): void {
  sendJson(ws, {type: 'entry_delta', index, delta});
}

export function sendCommit(ws: WebSocket, index: number): void {
  sendJson(ws, {type: 'entry_commit', index});
}

export function sendError(ws: WebSocket, code: string, message: string): void {
  sendJson(ws, {type: 'error', code, message});
}

export function sendSkip(ws: WebSocket, index: number): void {
  sendJson(ws, {type: 'entry_skip', index});
}

export function sendStreamEnd(ws: WebSocket): void {
  sendJson(ws, {type: 'stream_end'});
}

export function sendSessionList(ws: WebSocket, sessions: SessionSummaryFrame[]): void {
  sendJson(ws, {type: 'session_list', sessions});
}

export function sendConversationList(ws: WebSocket, conversations: ConversationSummary[]): void {
  sendJson(ws, {type: 'conversation_list', conversations});
}
import type {WsAuthenticator, HttpAuthMiddleware} from './types/auth.js';
import type {SessionStore} from './types/sessionStore.js';
import type {PromptBuilderConfig} from './infrastructure/builders/promptBuilder.js';
import type {ContextConfig} from './orchestration/conversationContext.js';
import type {ProviderConfig} from './providers/providerFactory.js';
import {withRetry} from './providers/withRetry.js';
import type {RetryPolicy} from './providers/withRetry.js';
import type {Logger} from './shared/logger.js';
import {setLogger} from './shared/logger.js';
import type {ChatSession} from './types/session.js';
import type {HalServer} from './transport/createServer.js';
import type {ConnectInfo} from './transport/ws/sessionResume.js';
import {PromptBuilder} from './infrastructure/builders/promptBuilder.js';
import {createChatOrchestrator} from './orchestration/chatOrchestrator.js';
import type {OrchestratorHooks} from './orchestration/chatOrchestrator.js';
import {createProvider} from './providers/providerFactory.js';
import {ToolRegistry} from './orchestration/tools/registry.js';
import {InMemorySessionStore} from './infrastructure/stores/inMemorySessionStore.js';
import {createApp} from './transport/createApp.js';
import type {HalAppOptions} from './transport/createApp.js';
import {createServer} from './transport/createServer.js';
import type {SessionResumeOptions} from './transport/ws/sessionResume.js';
import type {HistoryOptions} from './transport/createServer.js';

export interface HalEngineConfig {
  provider: ProviderConfig;
  resilience?: RetryPolicy;
  prompt: PromptBuilderConfig;
  tools?: ToolRegistry;
  session?: SessionStore;
  transport?: {
    port?: number;
    corsOrigin?: string | string[];
    basePath?: string;
    heartbeatIntervalMs?: number;
    additionalRoutes?: HalAppOptions['additionalRoutes'];
    rootRoutes?: HalAppOptions['rootRoutes'];
    errorHandler?: HalAppOptions['errorHandler'];
    resume?: SessionResumeOptions;
    history?: HistoryOptions;
  };
  auth: {
    ws: WsAuthenticator;
    http?: HttpAuthMiddleware;
  };
  orchestrator?: {
    maxToolRounds?: number;
    /** How long one tool call may take before it is abandoned and answered with a timeout result; default 30000, and 0 waits forever. */
    toolTimeoutMs?: number;
    contextConfig?: Partial<ContextConfig>;
    /** Lifecycle hooks: called before and after each phase of processing a user message. */
    hooks?: OrchestratorHooks;
  };
  // Replaces the package's logger process-wide, not per engine: there is one `log` per process.
  logger?: Logger;
  onConnect?: (session: ChatSession, connection: ConnectInfo) => void | Promise<void>;
  onDisconnect?: (sessionId: string) => void | Promise<void>;
}

export interface HalEngine extends HalServer {
  app: ReturnType<typeof createApp>;
  orchestrator: ReturnType<typeof createChatOrchestrator>;
  toolRegistry: ToolRegistry;
}

export function createHalEngine(config: HalEngineConfig): HalEngine {
  // Before anything else builds, so a supplied logger receives this engine's first line.
  if (config.logger) setLogger(config.logger);

  const toolRegistry = config.tools ?? new ToolRegistry();
  const sessionStore = config.session ?? new InMemorySessionStore();
  const basePath = config.transport?.basePath ?? '/hal';

  const baseProvider = createProvider(config.provider);
  const provider = config.resilience ? withRetry(baseProvider, config.resilience) : baseProvider;
  const promptBuilder = new PromptBuilder(config.prompt);
  const orchestrator = createChatOrchestrator(provider, promptBuilder, toolRegistry, {
    maxToolRounds: config.orchestrator?.maxToolRounds,
    toolTimeoutMs: config.orchestrator?.toolTimeoutMs,
    contextConfig: config.orchestrator?.contextConfig,
    hooks: config.orchestrator?.hooks,
    sessionStore,
  });

  const app = createApp({
    corsOrigin: config.transport?.corsOrigin,
    basePath,
    authMiddleware: config.auth.http,
    orchestrator,
    sessionStore,
    additionalRoutes: config.transport?.additionalRoutes,
    rootRoutes: config.transport?.rootRoutes,
    errorHandler: config.transport?.errorHandler,
  });

  const halServer = createServer({
    app,
    wsAuth: config.auth.ws,
    sessionStore,
    orchestrator,
    toolRegistry,
    basePath,
    port: config.transport?.port,
    heartbeatIntervalMs: config.transport?.heartbeatIntervalMs,
    onConnect: config.onConnect,
    onDisconnect: config.onDisconnect,
    resume: config.transport?.resume,
    history: config.transport?.history,
  });

  return {
    ...halServer,
    app,
    orchestrator,
    toolRegistry,
  };
}

 51	## The two shipped stores answer one order
 52	
 53	- `InMemorySessionStore` and `MongoSessionStore` list the same conversations in the same order, so a consumer swapping one for the other sees the same conversation list ([validated by: answer the same order for conversations whose activity differs](../../src/infrastructure/stores/storeListAgreement.test.ts#L43)).
 54	- They break a tie on activity the same way, by session id ([validated by: break a tie on activity the same way, by session id](../../src/infrastructure/stores/storeListAgreement.test.ts#L52)).
 55	- They page identically through the documented call, `listFor(userId, {limit, before: rows.at(-1)})`, a page at a time until a page comes back empty ([validated by: page the same way through the documented call, two rows at a time from the last row seen](../../src/infrastructure/stores/storeListAgreement.test.ts#L61)).
 56	
 57	## A cursor the caller can actually hold
 58	
 59	- A cursor's `updatedAt` may be a `Date`, an ISO string or an epoch number, so a summary that went through JSON on its way to a client and back still pages ([validated by: pages on a cursor that has been through JSON, and refuses one carrying no usable moment](../../src/infrastructure/stores/inMemoryConversationList.test.ts#L123)).
 60	- `MongoSessionStore` reads such a cursor as a date before it queries, since a string compares against no stored BSON date and would quietly match none of them ([validated by: pages on a cursor that has been through JSON, where a string would have matched no stored date](../../src/infrastructure/stores/mongo/mongoConversationList.test.ts#L150)).
 61	- A cursor carrying no usable moment is refused with an error naming it, rather than read as no cursor at all, which would answer the first page again and repeat rows a client has already shown ([validated by: pages on a cursor that has been through JSON, and refuses one carrying no usable moment](../../src/infrastructure/stores/inMemoryConversationList.test.ts#L123)).
 62	
 63	## A collection that cannot list
 64	
 65	- `find` is optional on `CollectionLike`, so an adapter written before conversation lists existed still satisfies the port ([validated by: refuses to list on a collection that implements no find, rather than reporting no conversations](../../src/infrastructure/stores/mongo/mongoConversationList.test.ts#L175)).
 66	- A store built on a collection without it refuses to list, rather than reporting that the user has no conversations ([validated by: refuses to list on a collection that implements no find, rather than reporting no conversations](../../src/infrastructure/stores/mongo/mongoConversationList.test.ts#L175)).
 67	
 68	## When the store cannot answer
 69	
 70	- A store whose collection fails rejects rather than answering a partial or empty list: what to show a user who may have conversations is the caller's decision, and an empty history is not a safe guess ([validated by: rejects rather than answering a partial list when the collection fails](../../src/infrastructure/stores/mongo/mongoConversationList.test.ts#L225)).
 71	
 72	## Over the WebSocket protocol
 73	
 74	- When `transport.history.enabled` is enabled without `transport.resume.enabled`, the server warns that listed conversation ids cannot be reopened ([validated by: warns when history is enabled without resume](../../src/transport/createServer.test.ts#L70)).
 75	- The newer `list_conversations` frame is opt-in through `transport.history.enabled`; it returns `conversation_list` summaries with ISO dates, uses the authenticated connection's user id, and answers `UNSUPPORTED` when disabled or when the store cannot list ([validated by: refuses conversation listing when history is enabled but the store cannot list](../../src/transport/ws/messageHandler.test.ts#L113)).
 76	- A history request is answered outside the per-session turn lock, so it can arrive before `stream_end` for an active user turn ([validated by: answers a conversation list while a user turn is still streaming](../../src/transport/ws/messageHandler.test.ts#L75)).
 77	
 78	- A client sends `{type: 'list_sessions', limit?, before?}` and receives `{type: 'session_list', sessions}` for the socket's authenticated user, with `createdAt` and `updatedAt` serialised as ISO-8601 strings and any client-supplied `userId` ignored ([validated by: answers list_sessions from the injected session store with ISO summaries](../../src/transport/ws/messageHandler.test.ts#L136), [validated by: answers list_sessions for the authenticated user with ISO dates, forwarding limit and before while ignoring any client userId](../../src/transport/conversationList.acceptance.test.ts#L91)).
 79	- A store without `listFor` answers `{type: 'session_list', sessions: []}`, and a throwing `listFor` logs an error on the `ws` category and answers `{type: 'error', code: 'SERVER_ERROR'}` ([validated by: answers an empty session_list when the store has no listFor, and SERVER_ERROR with a ws error log when listFor throws](../../src/transport/conversationList.acceptance.test.ts#L132), [validated by: logs list_sessions failures on ws with the authenticated user and answers SERVER_ERROR](../../src/transport/ws/messageHandler.test.ts#L170)).
